from g45_core import make_q, make_lesson
from fig_helpers_g45 import table_fig, bars_fig

def _q(b: int, n: int, d: str, p: str, c: str, w: list[str], e: str, h: str = '', fig=None):
    return make_q(f'TA5-B{b:02d}-{n:03d}', d, p, c, w, e, 'Tiếng Anh 5', h, fig)

